import unittest
from candidate import derivative


class TestDerivative(unittest.TestCase):
    def test_derivative_normal_case_polynomial_three_terms(self):
        self.assertEqual(derivative([1, 2, 3]), [2, 6])

    def test_derivative_normal_case_four_terms(self):
        self.assertEqual(derivative([3, 1, 2, 4, 5]), [1, 4, 12, 20])

    def test_derivative_empty_list(self):
        self.assertEqual(derivative([]), [])

    def test_derivative_single_element(self):
        self.assertEqual(derivative([5]), [])

    def test_derivative_two_elements(self):
        self.assertEqual(derivative([1, 2]), [2])

    def test_derivative_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            derivative(None)

    def test_derivative_non_iterable_raises_type_error(self):
        with self.assertRaises(TypeError):
            derivative(42)

    def test_derivative_float_coefficients(self):
        self.assertEqual(derivative([1.5, 2.0]), [2.0])

    def test_derivative_zero_coefficients(self):
        self.assertEqual(derivative([0, 0, 1]), [0, 2])

    def test_derivative_negative_coefficients(self):
        self.assertEqual(derivative([-3, -1, 2]), [-1, 4])
